const pages={overview:['Overview','RELATIONSHIP INTELLIGENCE','EXECUTIVE OVERVIEW','A connected view of customer relationships, financial products, service needs, and next best actions.'],customers:['Customer 360','CUSTOMER INTELLIGENCE','CUSTOMER 360','A unified customer relationship view with financial holdings, activity, service history, and next best actions.'],transactions:['Fraud & Transaction Intelligence','FINANCIAL ACTIVITY','FRAUD & TRANSACTION INTELLIGENCE','Explore customer transaction records with source stages, currencies, and potential review indicators.'],lending:['Lending & products','FINANCIAL RELATIONSHIP','LENDING & PRODUCTS','Understand credit exposure, repayment schedules, cards, payments, and term deposit maturities.'],service:['Service & engagement','CUSTOMER EXPERIENCE','SERVICE & ENGAGEMENT','Review service cases, interactions, consent, preferences, offers, and compliance follow-ups.'],'ai-chat':['AI Chat','DEEPSEEK ASSISTANT','AI CHAT','Ask questions about current banking records, customers, transactions, and investigation signals.'],health:['Data Integration','INTEGRATION OBSERVABILITY','DATA INTEGRATION','Configured source flow and available data freshness evidence.']};
