function stat(label,value,note,icon,tone='blue'){return`<article class="kpi-card"><div class="kpi-top"><span>${esc(label)}</span><i class="kpi-icon ${tone}">${icon}</i></div><strong>${esc(value)}</strong><small>${esc(note)}</small></article>`;}
